export const ANSWERS=['Color','Shape','Pattern / Marking','Object / Accessory','Visible Action','Physical State','Spatial Position'];
export function validBox(b,w,h){return !!b&&[b.x,b.y,b.width,b.height,w,h].every(Number.isFinite)&&w>0&&h>0&&b.x>=0&&b.y>=0&&b.width>0&&b.height>0&&b.x+b.width<=w&&b.y+b.height<=h&&b.width*b.height/(w*h)<.001;}
export function shuffled(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function poolFor(available,previous=[],count=100){const prev=new Set(previous);return [...shuffled(available.filter(x=>!prev.has(x))),...shuffled(available.filter(x=>prev.has(x)))].slice(0,count);}
export function qaErrors(s,img){const e=[];if(!s.question?.trim()||!s.answer?.trim())e.push('Nhập Question và Answer bằng tiếng Anh.');if(!['Attribute','Spatial','Relation'].includes(s.question_type))e.push('Question type không hợp lệ.');if(!ANSWERS.includes(s.answer_type))e.push('Answer type không hợp lệ.');if((s.question_type==='Spatial')!==(s.answer_type==='Spatial Position'))e.push('Spatial phải có answer type Spatial Position; các type khác không dùng vị trí làm answer.');if(s.question_type==='Spatial'&&(!s.references?.[0]?.trim()||s.references.filter(x=>x.trim()).length>2))e.push('Spatial cần mô tả 1–2 discrete reference objects.');if(!validBox(s.target_bbox,img?.width,img?.height))e.push('Cần một target bbox hợp lệ, diện tích < 0.1% ảnh gốc.');if(/^\s*(how many\b|is\b|are\b|does\b|do\b|can\b|has\b|have\b|was\b|were\b|will\b|would\b|could\b|should\b)/i.test(s.question||'')||/^(yes|no)\b/i.test(s.answer?.trim()||''))e.push('Không chấp nhận Count hoặc Yes/No.');return e;}
export function sampleErrors(s,img,otherIds){const e=qaErrors(s,img);if(!s.annotator?.trim())e.push('Nhập tên hoặc ID annotator.');if(s.selected?.length!==19||new Set(s.selected).size!==19)e.push('Cần đúng 19 OtherImages khác nhau.');if(s.selected?.some(id=>id===s.gt_id||!otherIds.includes(id)))e.push('OtherImages không hợp lệ hoặc trùng GT.');if(s.selected?.some(id=>!s.reviewed?.[id]))e.push('Mở và xác nhận lại tất cả 19 OtherImages.');if(!s.checks||s.checks.length!==5||s.checks.some(v=>v!==true))e.push('Hoàn thành 5 xác nhận chất lượng.');return e;}
// ZIP STORE: streamed entries, no external library; valid for archives below ZIP32 limits.
const table=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
function crc(bytes){let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
export async function zip(entries){let offset=0;const parts=[],central=[];const enc=new TextEncoder();if(entries.length>65535)throw Error('Quá nhiều file cho ZIP32.');for(const [name,blob]of entries){const path=enc.encode(name),bytes=new Uint8Array(await blob.arrayBuffer()),sum=crc(bytes);if(offset+bytes.length>0xffffffff)throw Error('Export lớn hơn 4 GB. Hãy export từng sample.');let head=new Uint8Array(30+path.length),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,sum,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,path.length,true);head.set(path,30);parts.push(head,blob);const c=new Uint8Array(46+path.length),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint32(16,sum,true);d.setUint32(20,bytes.length,true);d.setUint32(24,bytes.length,true);d.setUint16(28,path.length,true);d.setUint32(42,offset,true);c.set(path,46);central.push(c);offset+=head.length+bytes.length;}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,entries.length,true);e.setUint16(10,entries.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
